else: analyzer = Numbers3PatternAnalyzer(features_df) target = st.selectbox("対象", ["odd_count", "big_count"]) title = "奇数の個数の遷移確率" if target == "odd_count" else "大きい数字(5-9)の個数の遷移確率" fig = analyzer.transition_heatmap_fig(column=target, title=title) st.pyplot(fig, clear_figure=True)
