def initialize_performance_tracking_csv(filepath="results/ml_performance_tracking.csv"): """ 精度追跡CSVを初期化（既存の場合は何もしない） """ # ディレクトリがなければ作成 os.makedirs(os.path.dirname(filepath), exist_ok=True)
# ファイルが既に存在する場合はスキップ if os.path.exists(filepath): print(f"✓ {filepath} already exists. Skipping initialization.") return
# 空のDataFrameを作成してCSV保存 df = pd.DataFrame(columns=COLUMNS) df.to_csv(filepath, index=False, encoding="utf-8-sig") print(f"✓ Initialized {filepath}")
