if __name__ == "__main__": main()

"""
src.data.fetcher — スクレイピング

責務:
    - 楽天宝くじ Web サイトからの HTML テーブル取得
    - HTML レコードの正規化
    - 月単位の一括取得 (fetch_numbers3_by_month)
"""
from __future__ import annotations

import re
import time
from datetime import datetime, timedelta
from typing import Any, Dict, List, Optional, Sequence, Tuple

import pandas as pd

from src.utils.config import (
    ALIAS_MAP,
    COLUMNS,
    DEFAULT_SOURCE_TEMPLATES,
    PAYOUT_COLUMNS,
    SCRAPING_BACKOFF,
    SCRAPING_RETRIES,
    SCRAPING_SLEEP_SECONDS,
    SCRAPING_TIMEOUT,
)


# =====================================================================
# 内部ヘルパー
# =====================================================================


def _clean_digits(value: Any) -> Optional[str]:
    """数値以外の文字を除去して数字文字列を返す."""
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    digits = re.sub(r"[^0-9]", "", str(value))
    return digits if digits else None


def _col_contains(columns: Sequence, text: str) -> bool:
    return any(text in str(c) for c in columns)


def _extract_round_from_columns(columns: Sequence) -> Optional[str]:
    for col in columns[1:]:
        digits = _clean_digits(col)
        if digits:
            return digits
    return None


def _normalize_record(record: Dict) -> Dict:
    row: Dict[str, Any] = {}

    round_raw = record.get("回号")
    round_digits = _clean_digits(round_raw)
    if round_digits:
        row["回号"] = round_digits.zfill(4)

    draw_date = record.get("抽せん日") or record.get("抽選日")
    if draw_date:
        row["抽せん日"] = str(draw_date).strip()

    win_raw = record.get("当選番号") or record.get("当せん番号")
    win_digits = _clean_digits(win_raw)
    if win_digits:
        row["当選番号"] = win_digits.zfill(3)

    for key in PAYOUT_COLUMNS:
        val = record.get(key)
        digits = _clean_digits(val)
        if digits is not None:
            row[key] = int(digits)

    return row


def _table_to_records(df: pd.DataFrame) -> List[Dict]:
    records: List[Dict] = []
    df_work = df.copy()
    df_work.columns = [str(c).strip() for c in df_work.columns]

    if not df_work.empty and _col_contains(df_work.columns, "回号"):
        if _col_contains(df_work.columns, "当選番号") or _col_contains(
            df_work.columns, "当せん番号"
        ):
            for _, row in df_work.iterrows():
                records.append(row.to_dict())
            return records

    if not df_work.empty:
        header = [str(v).strip() for v in df_work.iloc[0].tolist()]
        if _col_contains(header, "回号") and (
            _col_contains(header, "当選番号") or _col_contains(header, "当せん番号")
        ):
            df_work = df_work.iloc[1:].copy()
            df_work.columns = header
            for _, row in df_work.iterrows():
                records.append(row.to_dict())
            return records

    if df_work.shape[1] >= 2:
        record = dict(zip(df_work.iloc[:, 0], df_work.iloc[:, 1]))
        round_digits = _extract_round_from_columns(df_work.columns)
        if round_digits:
            record["回号"] = round_digits
        records.append(record)
    return records


def _read_html_tables(
    url: str,
    timeout: int = SCRAPING_TIMEOUT,
    retries: int = SCRAPING_RETRIES,
    backoff: float = SCRAPING_BACKOFF,
) -> List[pd.DataFrame]:
    """URL から HTML テーブルを読み込む (リトライ付き)."""
    last_error: Optional[Exception] = None
    for attempt in range(retries):
        try:
            return pd.read_html(url, header=0)
        except Exception as exc:
            last_error = exc
            if attempt < retries - 1:
                time.sleep(backoff * (attempt + 1))
    raise last_error  # type: ignore[misc]


# =====================================================================
# 公開 API
# =====================================================================


def fetch_numbers3_by_month(
    start_date: datetime,
    end_date: datetime,
    sleep_seconds: float = SCRAPING_SLEEP_SECONDS,
    source_templates: Optional[List[str]] = None,
    fail_fast: bool = True,
    timeout: int = SCRAPING_TIMEOUT,
    retries: int = SCRAPING_RETRIES,
    backoff: float = SCRAPING_BACKOFF,
) -> Tuple[pd.DataFrame, List[Dict]]:
    """月単位でスクレイピングして (DataFrame, failures) を返す."""
    rows: List[Dict] = []
    failures: List[Dict] = []

    current = datetime(start_date.year, start_date.month, 1)
    last_month = datetime(end_date.year, end_date.month, 1)

    if source_templates is None:
        source_templates = list(DEFAULT_SOURCE_TEMPLATES)

    while current <= last_month:
        yyyymm = current.strftime("%Y%m")
        success = False
        last_error: Optional[Exception] = None

        for template in source_templates:
            url = template.format(yyyymm=yyyymm)
            try:
                tables = _read_html_tables(
                    url, timeout=timeout, retries=retries, backoff=backoff
                )
                for tbl in tables:
                    records = _table_to_records(tbl)
                    for record in records:
                        if "当選番号" not in record and "当せん番号" not in record:
                            continue
                        row = _normalize_record(record)
                        if row.get("回号") and row.get("当選番号"):
                            rows.append(row)
                success = True
                break
            except Exception as e:
                if fail_fast:
                    raise
                last_error = e
                print(f"[WARN] {yyyymm} failed: {e}")

        if not success:
            if last_error is not None:
                failures.append({"month": yyyymm, "error": str(last_error)})
            print(f"[SKIP] {yyyymm}")

        time.sleep(sleep_seconds)
        current = (current.replace(day=28) + timedelta(days=4)).replace(day=1)

    return pd.DataFrame(rows), failures

"""
src.data.loader — データ取得・クレンジング

責務:
    - CSV の読み書き・正規化
    - バリデーション
    - スクレイピング関数は src.data.fetcher に分離
      (後方互換のため fetch_numbers3_by_month を re-export)
"""
from __future__ import annotations

import re
import shutil
from datetime import datetime
from pathlib import Path
from typing import Any, Dict, List, Optional, Sequence, Tuple

import numpy as np
import pandas as pd

from src.utils.config import ALIAS_MAP, COLUMNS, PAYOUT_COLUMNS

# --- fetcher から re-export (後方互換) ---
from src.data.fetcher import (  # noqa: F401
    fetch_numbers3_by_month,
    _read_html_tables,
    _clean_digits,
)


# =====================================================================
# 内部ヘルパー
# =====================================================================


def _normalize_winning_number_series(series: pd.Series) -> pd.Series:
    cleaned = series.apply(_clean_digits)
    return cleaned.apply(lambda x: x.zfill(3) if isinstance(x, str) else None)


# =====================================================================
# 公開関数
# =====================================================================

def normalize_numbers3_columns(df: pd.DataFrame) -> pd.DataFrame:
    """列名エイリアスの正規化."""
    if df is None:
        raise ValueError("normalize_numbers3_columns: df is None")
    if not isinstance(df, pd.DataFrame):
        raise TypeError(
            f"normalize_numbers3_columns: expected DataFrame, got {type(df)}"
        )
    df = df.copy()
    for old, new in ALIAS_MAP.items():
        if old in df.columns:
            if new in df.columns:
                df[new] = df[new].fillna(df[old])
                df = df.drop(columns=[old])
            else:
                df = df.rename(columns={old: new})
    return df


def add_digit_columns(df: pd.DataFrame) -> pd.DataFrame:
    """当選番号から百・十・一の位を分解して列に追加する."""
    df = df.copy()
    if "当選番号" not in df.columns:
        if "当せん番号" in df.columns:
            df["当選番号"] = df["当せん番号"]
        else:
            raise KeyError("当選番号（または当せん番号）列が必要です。")
    num = df["当選番号"].astype(str).str.zfill(3)
    df["digit_h"] = num.str[0].astype(int)
    df["digit_t"] = num.str[1].astype(int)
    df["digit_o"] = num.str[2].astype(int)
    return df


def _coverage_ratio(df: pd.DataFrame) -> Optional[float]:
    if "回号" not in df.columns:
        return None
    rounds = pd.to_numeric(df["回号"], errors="coerce").dropna().astype(int)
    if rounds.empty:
        return None
    min_r, max_r = rounds.min(), rounds.max()
    total_range = max_r - min_r + 1
    if total_range <= 0:
        return None
    return rounds.nunique() / total_range


def update_numbers3_clean(
    clean_path: str = "numbers3_clean.csv",
    backup: bool = True,
    sleep_seconds: float = 1,
    force_full: bool = False,
) -> pd.DataFrame:
    """差分取得してクリーンCSVを更新する."""
    path = Path(clean_path)

    if path.exists() and not force_full:
        df_existing = pd.read_csv(path)
        df_existing = normalize_numbers3_columns(df_existing)
        if "当選番号" in df_existing.columns:
            df_existing["当選番号"] = _normalize_winning_number_series(
                df_existing["当選番号"]
            )
    else:
        df_existing = pd.DataFrame(columns=COLUMNS)

    if force_full or df_existing.empty:
        start_date = datetime(1994, 10, 1)
    else:
        dates = pd.to_datetime(df_existing.get("抽せん日"), errors="coerce")
        last_date = dates.max()
        if pd.isna(last_date):
            start_date = datetime(1994, 10, 1)
        else:
            start_date = datetime(last_date.year, last_date.month, 1)

    new_df, _failures = fetch_numbers3_by_month(
        start_date,
        datetime.now(),
        sleep_seconds=sleep_seconds,
    )

    if new_df is None or new_df.empty:
        print("新規データなし。既存データを返します。")
        return df_existing

    new_df = normalize_numbers3_columns(new_df)
    if "当選番号" in new_df.columns:
        new_df["当選番号"] = _normalize_winning_number_series(new_df["当選番号"])

    combined = pd.concat([df_existing, new_df], ignore_index=True)
    combined = normalize_numbers3_columns(combined)

    if "回号" in combined.columns:
        combined["回号"] = combined["回号"].astype(str).str.zfill(4)
        combined = combined.drop_duplicates(subset=["回号"], keep="last")
        combined = combined.sort_values("回号", key=lambda s: s.astype(int))

    ordered_cols = [c for c in COLUMNS if c in combined.columns]
    combined = combined[ordered_cols]

    if backup and path.exists():
        shutil.copy2(path, path.with_suffix(".csv.bak"))

    combined.to_csv(path, index=False, encoding="utf-8-sig")
    print(f"更新完了: {len(combined)} 件")
    return combined


def backfill_numbers3_range(
    clean_path: str,
    start_date: datetime,
    end_date: datetime,
    backup: bool = True,
    sleep_seconds: float = 1,
) -> pd.DataFrame:
    """指定期間のデータをバックフィルする."""
    path = Path(clean_path)
    if path.exists():
        df_existing = pd.read_csv(path)
        df_existing = normalize_numbers3_columns(df_existing)
        if "当選番号" in df_existing.columns:
            df_existing["当選番号"] = _normalize_winning_number_series(
                df_existing["当選番号"]
            )
    else:
        df_existing = pd.DataFrame(columns=COLUMNS)

    new_df, _failures = fetch_numbers3_by_month(
        start_date, end_date, sleep_seconds=sleep_seconds
    )
    new_df = normalize_numbers3_columns(new_df)
    if "当選番号" in new_df.columns:
        new_df["当選番号"] = _normalize_winning_number_series(new_df["当選番号"])

    combined = pd.concat([df_existing, new_df], ignore_index=True)
    combined = normalize_numbers3_columns(combined)
    if "当選番号" in combined.columns:
        combined["当選番号"] = _normalize_winning_number_series(combined["当選番号"])
    if "回号" in combined.columns:
        combined["回号"] = combined["回号"].astype(str).str.zfill(4)
        combined = combined.drop_duplicates(subset=["回号"], keep="last")
        combined = combined.sort_values(by="回号", key=lambda s: s.astype(int))

    ordered_cols = [c for c in COLUMNS if c in combined.columns]
    if ordered_cols:
        combined = combined[ordered_cols]

    if backup and path.exists():
        backup_path = path.with_suffix(path.suffix + ".bak")
        shutil.copy2(path, backup_path)
        print(f"バックアップ保存: {backup_path}")

    combined.to_csv(path, index=False, encoding="utf-8-sig")
    print(f"更新完了: {len(combined)}件を {path.name} に保存しました。")
    return combined


def validate_numbers3(
    df: pd.DataFrame,
    strict: bool = True,
    allow_missing_rounds: bool = True,
) -> List[str]:
    """データの整合性チェック."""
    errors: List[str] = []
    warnings: List[str] = []
    df = normalize_numbers3_columns(df)
    if "当選番号" in df.columns:
        df["当選番号"] = _normalize_winning_number_series(df["当選番号"])

    if "回号" in df.columns:
        rounds = df["回号"].astype(str)
        round_nums = pd.to_numeric(rounds, errors="coerce")
        if round_nums.isna().any():
            errors.append("回号に数値化できない値があります。")
        else:
            round_nums = round_nums.astype(int)
            duplicates = rounds[rounds.duplicated()].unique().tolist()
            if duplicates:
                errors.append(f"回号の重複: {duplicates[:10]}")

            if not round_nums.empty:
                min_r, max_r = round_nums.min(), round_nums.max()
                missing = sorted(set(range(min_r, max_r + 1)) - set(round_nums))
                if missing:
                    message = f"回号の欠番: {missing[:10]}"
                    if allow_missing_rounds:
                        warnings.append(message)
                    else:
                        errors.append(message)

    if "当選番号" in df.columns:
        invalid = df[
            df["当選番号"].isna()
            | ~df["当選番号"].astype(str).str.fullmatch(r"\d{3}")
        ]
        if not invalid.empty:
            errors.append("当選番号が3桁でない行があります。")

    if errors and strict:
        raise ValueError(" / ".join(errors))

    if errors:
        print("警告:", " / ".join(errors))
    if warnings:
        print("注意:", " / ".join(warnings))

    return errors + warnings

"""
src.models.statistical — ルールベース予測器

責務:
    - Numbers3Predictor (遷移行列・合計確率・インターバル等に基づく統計予測)
"""
from __future__ import annotations

from typing import Dict, List

import numpy as np
import pandas as pd

from src.data.loader import normalize_numbers3_columns
from src.models.base import BasePredictor, _box_type
from src.utils.config import PREDICTION_MODELS


class Numbers3Predictor(BasePredictor):
    """統計ベースの予測器."""

    def __init__(self, df: pd.DataFrame):
        self.df = df.copy()
        self._ensure_features()
        if "回号" in self.df.columns:
            self.df["回号"] = pd.to_numeric(self.df["回号"], errors="coerce")
        self.df = (
            self.df.sort_values("回号").dropna(subset=["回号"]).reset_index(drop=True)
        )

    # ------------------------------------------------------------------
    def _ensure_features(self):
        if "当選番号" not in self.df.columns:
            if "当せん番号" in self.df.columns:
                self.df["当選番号"] = self.df["当せん番号"]
            else:
                raise KeyError("当選番号（または当せん番号）列が必要です。")

        num = self.df["当選番号"].astype(str).str.zfill(3)
        self.df["digit_h"] = num.str[0].astype(int)
        self.df["digit_t"] = num.str[1].astype(int)
        self.df["digit_o"] = num.str[2].astype(int)

        self.df["odd_count"] = (
            (self.df[["digit_h", "digit_t", "digit_o"]] % 2 == 1).sum(axis=1)
        )
        self.df["big_count"] = (
            (self.df[["digit_h", "digit_t", "digit_o"]] >= 5).sum(axis=1)
        )
        self.df["digit_sum"] = self.df[["digit_h", "digit_t", "digit_o"]].sum(
            axis=1
        )

    # ------------------------------------------------------------------
    def _get_transition_matrix(self, column: str) -> pd.DataFrame:
        current = self.df[column]
        nxt = self.df[column].shift(-1)
        return pd.crosstab(current, nxt, normalize="index")

    def _get_digit_intervals(self) -> Dict[str, Dict[int, int]]:
        intervals: Dict[str, Dict[int, int]] = {
            "digit_h": {},
            "digit_t": {},
            "digit_o": {},
        }
        last_index = self.df.index[-1]
        for col in ["digit_h", "digit_t", "digit_o"]:
            for n in range(10):
                series = self.df[col]
                locs = series[series == n].index
                if len(locs) > 0:
                    gap = last_index - locs[-1]
                else:
                    gap = len(self.df)
                intervals[col][n] = gap
        return intervals

    def _get_sum_probabilities(self) -> np.ndarray:
        p = np.ones(10) / 10.0
        p_sum = np.convolve(p, p)
        p_sum = np.convolve(p_sum, p)
        return p_sum

    def _get_digit_frequencies(
        self, window: int = 200
    ) -> Dict[str, Dict[int, float]]:
        df_slice = self.df if (window is None or window <= 0) else self.df.tail(window)
        freqs: Dict[str, Dict[int, float]] = {}
        for col in ["digit_h", "digit_t", "digit_o"]:
            counts = df_slice[col].value_counts(normalize=True)
            freqs[col] = {i: float(counts.get(i, 0.0)) for i in range(10)}
        return freqs

    def validate_interval_correlation(self, column: str = "digit_h") -> Dict:
        """ハマリ回数と次回出現の相関を検証（ギャンブラーの誤謬チェック）."""
        try:
            from scipy.stats import pearsonr
        except ImportError:
            return {"error": "scipy が必要です: pip install scipy"}

        results: Dict = {}
        for n in range(10):
            is_n = self.df[column] == n
            gap_list: List[int] = []
            gap = 0
            for val in is_n:
                if val:
                    gap_list.append(gap)
                    gap = 0
                else:
                    gap += 1
            if len(gap_list) < 20:
                continue
            gaps = np.array(gap_list)
            corr, pval = pearsonr(gaps[:-1], gaps[1:])
            results[n] = {
                "correlation": round(float(corr), 4),
                "p_value": round(float(pval), 4),
            }

        significant = sum(1 for r in results.values() if r["p_value"] < 0.05)
        total = len(results)
        return {
            "column": column,
            "per_digit": results,
            "significant_count": significant,
            "total_tested": total,
            "conclusion": (
                "相関なし（ギャンブラーの誤謬）"
                if significant <= max(1, int(total * 0.1))
                else f"{significant}/{total} 個の数字で有意な相関あり"
            ),
        }

    # ------------------------------------------------------------------
    def predict(
        self,
        top_n: int = 20,
        model: str = "hybrid",
        recent_window: int = 200,
        interval_weight: float = 0.0,
        verbose: bool = True,
    ) -> pd.DataFrame:
        """統計ベース予測."""
        model = model.lower()
        supported = {
            "hybrid",
            "transition_sum",
            "interval_sum",
            "sum_only",
            "frequency",
            "recent_frequency",
            "interval_boost",
        }
        if model not in supported:
            raise ValueError(f"Unsupported model: {model}")

        use_transition = model in {"hybrid", "transition_sum"}
        use_interval = model in {"hybrid", "interval_sum", "interval_boost"}
        use_sum = True
        use_frequency = model in {"frequency", "recent_frequency"}
        if model == "interval_boost":
            interval_weight = max(interval_weight, 0.3)

        if use_interval and interval_weight > 0 and verbose:
            print(
                "⚠️ 注意: ハマリ係数はギャンブラーの誤謬に該当し得ます。"
                "validate_interval_correlation() で効果を検証してください。"
            )

        trans_odd = (
            self._get_transition_matrix("odd_count") if use_transition else None
        )
        trans_big = (
            self._get_transition_matrix("big_count") if use_transition else None
        )

        last_row = self.df.iloc[-1]
        current_odd = last_row["odd_count"]
        current_big = last_row["big_count"]
        current_num = last_row["当選番号"]
        if verbose:
            print(
                f"直近の結果: 回号={last_row['回号']}, 番号={current_num}, "
                f"奇数={current_odd}個, Big={current_big}個"
            )

        intervals = self._get_digit_intervals() if use_interval else None
        sum_probs = self._get_sum_probabilities() if use_sum else None
        freqs = (
            self._get_digit_frequencies(window=recent_window)
            if use_frequency
            else None
        )

        candidates: List[Dict] = []
        for n in range(1000):
            s_num = f"{n:03d}"
            h, t, o = int(s_num[0]), int(s_num[1]), int(s_num[2])

            c_sum = h + t + o
            c_odd = (h % 2) + (t % 2) + (o % 2)
            c_big = (1 if h >= 5 else 0) + (1 if t >= 5 else 0) + (1 if o >= 5 else 0)

            if use_transition:
                try:
                    prob_odd_trans = trans_odd.loc[current_odd, c_odd]
                except KeyError:
                    prob_odd_trans = 0
                try:
                    prob_big_trans = trans_big.loc[current_big, c_big]
                except KeyError:
                    prob_big_trans = 0
                pattern_score = prob_odd_trans * prob_big_trans
            else:
                pattern_score = 1.0

            sum_score = sum_probs[c_sum] if use_sum else 1.0

            if use_interval:
                total_gap = (
                    intervals["digit_h"][h]
                    + intervals["digit_t"][t]
                    + intervals["digit_o"][o]
                )
                interval_bonus = 1.0 + np.log1p(total_gap) * interval_weight
            else:
                total_gap = 0
                interval_bonus = 1.0

            if use_frequency:
                freq_score = (
                    freqs["digit_h"][h] * freqs["digit_t"][t] * freqs["digit_o"][o]
                )
            else:
                freq_score = 1.0

            final_score = pattern_score * sum_score * interval_bonus * freq_score
            box_t, box_count = _box_type(s_num)

            candidates.append(
                {
                    "モデル": model,
                    "予測番号": s_num,
                    "総合スコア": final_score,
                    "パターン確率": pattern_score if use_transition else 0.0,
                    "合計値確率": sum_score if use_sum else 0.0,
                    "頻度スコア": freq_score if use_frequency else 0.0,
                    "ハマリ係数": interval_bonus,
                    "直前ギャップ和": total_gap,
                    "合計": c_sum,
                    "奇数数": c_odd,
                    "Big数": c_big,
                    "タイプ": box_t,
                    "ボックス通り数": box_count,
                }
            )

        df_pred = pd.DataFrame(candidates)
        df_pred = df_pred.sort_values("総合スコア", ascending=False).reset_index(
            drop=True
        )

        if not df_pred.empty:
            max_score = df_pred["総合スコア"].max()
            if max_score > 0:
                df_pred["総合スコア"] = (
                    df_pred["総合スコア"] / max_score * 100.0
                ).round(1)

        if verbose and not df_pred.empty:
            top = df_pred.iloc[0]
            print(
                f"予測根拠: 番号={top['予測番号']}, スコア={top['総合スコア']}"
                f", パターン={top['パターン確率']:.3f}"
                f", 合計={top['合計値確率']:.3f}"
                f", ハマリ={top['ハマリ係数']:.2f}"
                f", 奇数={top['奇数数']}, Big={top['Big数']}"
                f", {top['タイプ']}({top['ボックス通り数']}通り)"
            )

        return df_pred.head(top_n)

    # ------------------------------------------------------------------
    def predict_next(self) -> str:
        """Top-1 の予測番号を返す."""
        result = self.predict(top_n=1, model="hybrid", verbose=False)
        if result.empty:
            return "000"
        return str(result.iloc[0]["予測番号"])

from datetime import datetime, timedelta
import pandas as pd
from numbers3_logic import Numbers3MLPredictor
def _make_sample_df(count=80): start = datetime(2024, 1, 1) rows = [] for i in range(count): draw_date = start + timedelta(days=i) num = f"{i % 10}{(i * 3) % 10}{(i * 7) % 10}" rows.append( { "回号": str(1000 + i), "抽せん日": draw_date.strftime("%Y-%m-%d"), "当選番号": num, } ) return pd.DataFrame(rows)
def test_ml_predictor_train_and_predict(): df = _make_sample_df() predictor = Numbers3MLPredictor(df, num_boost_round=10, random_state=0) predictor.train() result = predictor.predict_next() assert isinstance(result, str) assert len(result) == 3 assert result.isdigit()
def test_ml_predictor_tune_hyperparams(): df = _make_sample_df(count=120) predictor = Numbers3MLPredictor(df, num_boost_round=5, random_state=1) result = predictor.tune_hyperparams( param_grid={ "learning_rate": [0.1], "num_leaves": [15, 31], "max_depth": [-1], "min_child_samples": [10], }, valid_size=20, ) assert isinstance(result, dict) assert "best_params" in result assert "valid_logloss" in result

import unittest
